args.command:
New-Item -ItemType Directory -Force -Path 'tmp\bfs' | Out-Null
$files = @(
  'https://www2.census.gov/ces/bfs/HBA_ST.xlsx',
  'https://www2.census.gov/ces/bfs/SBF8Q_ST.xlsx',
  'https://www2.census.gov/ces/bfs/BF8Q_ST.xlsx',
  'https://www2.census.gov/ces/bfs/BA_ST.xlsx',
  'https://www2.census.gov/econ/bfs/csv/bfs_us_apps_monthly.csv',
  'https://www2.census.gov/programs-surveys/eits/tables/time-series/data/business-formation-statistics/bfs_month.csv'
)
foreach ($u in $files) {
  $name = Split-Path $u -Leaf
  $out = "tmp\bfs\$name"
  try {
    Invoke-WebRequest -Uri $u -OutFile $out -UseBasicParsing -TimeoutSec 60
    $len = (Get-Item $out).Length
    Write-Output "OK $name $len"
  } catch {
    Write-Output "FAIL $name :: $($_.Exception.Message)"
  }
}

