};

const REGION_COLORS: Record<Region, string> = {
  Northeast: "#0369a1",
  Midwest: "#0f766e",
  South: "#c2410c",
  West: "#7c3aed",
};

const fmt1 = (n: number) => n.toFixed(1);
const fmt0 = (n: number) =>
  n >= 1_000_000
    ? `${(n / 1_000_000).toFixed(2)}M`
    : n >= 1_000
      ? `${(n / 1_000).toFixed(0)}k`
      : String(n);

